arguments.content:
import { test } from 'node:test';
import assert from 'node:assert/strict';

import {
  collides,
  step,
  makeBricks,
  createState,
  BRICK_ROWS,
  BRICK_COLS,
  WIDTH,
  UP,
  DOWN,
  LEFT,
  RIGHT,
  frame,
} from './neon.js';

test('collides: clear overlap detected', () => {
  const ball = { x: 100, y: 100, r: 8 };
  const brick = { x: 90, y: 90, w: 40, h: 20 };
  assert.equal(collides(ball, brick), true);
});

test('collides: ball clearly away => no collision', () => {
  const ball = { x: 300, y: 300, r: 8 };
  const brick = { x: 90, y: 90, w: 40, h: 20 };
  assert.equal(collides(ball, brick), false);
});

test('collides: edge contact (radius) detected', () => {
  const ball = { x: 85, y: 100, r: 8 }; // right edge of the ball at 93 > 90
  const brick = { x: 90, y: 90, w: 40, h: 20 };
  assert.equal(collides(ball, brick), true);
});

test('step: bounce off the left wall', () => {
  const state = createState(1);
  state.ball = { x: 2, y: 200, r: 7, vx: -300, vy: 0 };
  step(state, 1 / 60);
  assert.ok(state.ball.vx > 0, 'horizontal velocity should flip to the right');
});

test('step: ball exiting through the bottom => lost', () => {
  const state = createState(1);
  state.ball = { x: 320, y: 500, r: 7, vx: 0, vy: 400 };
  const lost = step(state, 1 / 60);
  assert.equal(lost, true);
});

test('makeBricks: full, all-alive grid at start', () => {
  const bricks = makeBricks(1);
  assert.equal(bricks.length, BRICK_ROWS * BRICK_COLS);
  assert.ok(bricks.every((b) => b.alive));
  assert.ok(bricks.every((b) => b.x >= 0 && b.x + b.w <= WIDTH));
});

// --- Issue #1: Brick Bounce Tests ---

// Mock context for frame()
const mockCtx = {
  fillRect: () => {},
  beginPath: () => {},
  arc: () => {},
  fill: () => {},
  fillText: () => {},
};

test('brick bounce: top face hit flips vy', () => {
  const state = createState(1);
  // Ball is moving UP, hits the bottom edge of a brick
  state.ball = { x: 100, y: 110, r: 7, vx: 0, vy: 200 * UP }; 
  const brick = { x: 80, y: 100, w: 40, h: 20, alive: true, points: 10 };
  state.bricks = [brick];

  frame(mockCtx, state);

  assert.equal(Math.sign(state.ball.vy), DOWN, 'Ball should bounce DOWN');
  assert.ok(state.ball.y > 100 + 20, 'Ball should be pushed out of the brick');
});

test('brick bounce: bottom face hit flips vy', () => {
  const state = createState(1);
  // Ball is moving DOWN, hits the top edge of a brick
  state.ball = { x: 100, y: 90, r: 7, vx: 0, vy: 200 * DOWN }; 
  const brick = { x: 80, y: 100, w: 40, h: 20, alive: true, points: 10 };
  state.bricks = [brick];

  frame(mockCtx, state);

  assert.equal(Math.sign(state.ball.vy), UP, 'Ball should bounce UP');
  assert.ok(state.ball.y < 100, 'Ball should be pushed out of the brick');
});

test('brick bounce: left face hit flips vx', () => {
  const state = createState(1);
  // Ball moving RIGHT, hits left edge of brick
  state.ball = { x: 75, y: 110, r: 7, vx: 200 * RIGHT, vy: 0 }; 
  const brick = { x: 80, y: 100, w: 40, h: 20, alive: true, points: 10 };
  state.bricks = [brick];

  frame(mockCtx, state);

  assert.equal(Math.sign(state.ball.vx), LEFT, 'Ball should bounce LEFT');
  assert.ok(state.ball.x < 80, 'Ball should be pushed out of the brick');
});

test('brick bounce: right face hit flips vx', () => {
  const state = createState(1);
  // Ball moving LEFT, hits right edge of brick
  state.ball = { x: 125, y: 110, r: 7, vx: 200 * LEFT, vy: 0 }; 
  const brick = { x: 80, y: 100, w: 40, h: 20, alive: true, points: 10 };
  state.bricks = [brick];

  frame(mockCtx, state);

  assert.equal(Math.sign(state.ball.vx), RIGHT, 'Ball should bounce RIGHT');
  assert.ok(state.ball.x > 120, 'Ball should be pushed out of the brick');
});

test('brick bounce: corner hit flips both', () => {
  const state = createState(1);
  // Diagonal hit
  state.ball = { x: 75, y: 95, r: 7, vx: 200 * RIGHT, vy: 200 * UP }; 
  const brick = { x: 80, y: 100, w: 40, h: 20, alive: true, points: 10 };
  state.bricks = [brick];

  frame(mockCtx, state);

  assert.equal(Math.sign(state.ball.vx), LEFT);
  assert.equal(Math.sign(state.ball.vy), DOWN);
});

test('brick bounce: tunneling prevention (sweep)', () => {
  const state = createState(1);
  state.ball = { x: 100, y: 90, r: 7, vx: 0, vy: 1200 * DOWN };
  const brick = { x: 80, y: 100, w: 40, h: 20, alive: true, points: 10 };
  state.bricks = [brick];

  step(state, 0.05);
  frame(mockCtx, state);

  assert.equal(brick.alive, false, 'Brick should be broken even if the ball jumped over it');
});

